public void avaActive_WHSShipmentTableUnassignedDS()
{
    if (AVASalesTableUnassigned)
    {
        AVASalesTableInfoFields_ShipmentsSales.enabled(true);
        AVASalesTableInfoFields_ShipmentsSales.visible(true);
        AVASalesTableInfoFields_ShipmentsTransfer.enabled(false);
        AVASalesTableInfoFields_ShipmentsTransfer.visible(false);
    }
    else if (AVAInventTransferTableUnassigned)
    {
        AVASalesTableInfoFields_ShipmentsSales.enabled(false);
        AVASalesTableInfoFields_ShipmentsSales.visible(false);
        AVASalesTableInfoFields_ShipmentsTransfer.enabled(true);
        AVASalesTableInfoFields_ShipmentsTransfer.visible(true);
    }
    else
    {
        AVASalesTableInfoFields_ShipmentsSales.enabled(false);
        AVASalesTableInfoFields_ShipmentsSales.visible(true);
        AVASalesTableInfoFields_ShipmentsTransfer.enabled(false);
        AVASalesTableInfoFields_ShipmentsTransfer.visible(false);
    }
}
